<?php require_once __DIR__.'/config/config.php'; $pageTitle='About IFAB'; $bodyClass='reference-marketplace'; $videoRows=db()->query("SELECT title, youtube_url, description FROM site_videos WHERE status='active' ORDER BY created_at DESC")->fetchAll(); require __DIR__.'/includes/header.php'; ?>
<main class="page-wrap"><span class="eyebrow">ABOUT IFAB</span><h1 class="page-title">Rooted in flowers.<br><em>Growing through connection.</em></h1><p class="lead">IFAB Flower Exchange is presented here as a digital platform concept for bringing growers, buyers and flower-market operations together.</p><div class="about-panel"><h2>Our purpose</h2><p>To make flower discovery and trade more organised through accessible listings, auction workflows, transparent information and useful digital tools.</p></div><?php if($videoRows): ?><section class="about-videos"><div class="section-heading"><div><span class="eyebrow">FROM THE IFAB COLLECTION</span><h2>See the flowers in motion</h2></div><p>Watch videos shared by the IFAB team and flower growers.</p></div><div class="about-video-grid"><?php foreach($videoRows as $video): $embedUrl=youtube_embed_url((string)$video['youtube_url']); if($embedUrl==='') continue; ?><article class="about-video-card"><div class="video-frame"><iframe src="<?= e($embedUrl) ?>" title="<?= e($video['title']) ?> video" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><span>ABOUT VIDEO</span><h3><?= e($video['title']) ?></h3><?php if (!empty($video['description'])): ?><p><?= e($video['description']) ?></p><?php endif; ?></article><?php endforeach; ?></div></section><?php endif; ?></main><?php require __DIR__.'/includes/footer.php'; ?>
